+		return
+	}
+	b.mu.Lock()
+	defer b.mu.Unlock()
+	if b.closed || len(b.cursors) == 0 {
+		return
+	}
+	for _, item := range items {
+		b.expireLocked()
+		if len(b.cursors) == 0 {
+			b.clearLocked()
+			break
+		}
